__LOADERS["catalog"] = function(...)
-- =====================================================================
-- Lib: catalog/pagination helpers for plugin catalogs: hasNextPage,
--      nextIndex/pageUrl (dominant "?page=N" scheme), urlEncode.
-- Loaded via require_lib("catalog"). No dependencies on other libs.
-- =====================================================================
local version = "1.0.1"

local M = {}

-- =====================================================================
-- Pagination
-- =====================================================================

-- "Has next page" for the dominant scheme where a page is considered
-- non-final as long as it returned any item (39 inline copies of
-- `#items > 0`, plus 7 local hasNextPage helpers with the same body).
-- Plugins that know their total page count keep their own comparison.
function M.hasNextPage(items)
    return type(items) == "table" and #items > 0
end

-- Catalog index is 0-based; pages on the wire are 1-based — the
-- dominant `local page = index + 1` from 74 plugins.
function M.nextIndex(index)
    return (index or 0) + 1
end

-- Build a page URL from a template with "{n}" where the 1-based page
-- number goes. Matches the dominant string-concat schemes:
--   ".../catalog?page={n}"        (guide, most sites)
--   "...&pg={n}"                  (en/scribblehub.lua:33)
--   "...&bpage={n}"               (ru/bookhamster.lua:85)
-- Sites with conditional page params or API cursors keep their own code.
function M.pageUrl(template, index)
    return (template:gsub("{n}", tostring(M.nextIndex(index))))
end

-- =====================================================================
-- Query encoding
-- =====================================================================

-- Pure-Lua mirror of the engine global url_encode (Java
-- URLEncoder.encode(s, "UTF-8"): application/x-www-form-urlencoded —
-- space -> "+", unreserved A-Za-z0-9 . - * _ kept, everything else
-- "%XX" uppercase over UTF-8 bytes, "\n" normalized to "\r\n" first).
-- The 73 plugin call sites use the engine global directly; this copy
-- exists for shared libs and parity tests outside the engine.
-- Byte-wise whitelist: LuaJ's %w matches Latin-1 letters (0xC0-0xFF), so a
-- UTF-8 byte like 0xE3 would stay raw and corrupt the query (CJK/Cyrillic
-- search returned 0). Java URLEncoder keeps only A-Z a-z 0-9 . - * _.
local function unreserved(b)
    return (b >= 48 and b <= 57)
        or (b >= 65 and b <= 90)
        or (b >= 97 and b <= 122)
        or b == 45 or b == 46 or b == 42 or b == 95
end

function M.urlEncode(s)
    if type(s) ~= "string" then return s end
    s = s:gsub("\n", "\r\n")
    return (s:gsub(".", function(c)
        local b = string.byte(c)
        if b == 32 then return "+" end
        if unreserved(b) then return c end
        return string.format("%%%02X", b)
    end))
end

return M
end

__LOADERS["content"] = function(...)
-- =====================================================================
-- Lib: chapter-text cleanup shared by the novel extractors.
-- Loaded via require_lib("content"). No dependencies on other libs.
--
-- Engine API used inside the functions only: string_normalize,
-- regex_replace, string_trim (all guarded, so the module still loads
-- outside the app).
-- =====================================================================
local version = "1.0.0"

local M = {}

local function logErr(msg)
    if type(log_error) == "function" then log_error(msg) end
end

local function trim(s)
    return (s:gsub("^%s+", ""):gsub("%s+$", ""))
end

-- Chapter-heading prefix that gets stripped when it duplicates the
-- chapter title the engine already shows (guide:823). Language picks the
-- word for the ordinal; unknown/missing lang falls back to the dominant
-- ru/en cluster (Глава N | Chapter N).
local HEAD_BY_LANG = {
    ru = "(Глава\\s+\\d+|Chapter\\s+\\d+)",
    en = "(Chapter\\s+\\d+)",
    zh = "(第[\\d一二三四五六七八九十百]+[章节卷回部集篇]|Chapter\\s+\\d+)",
    ja = "(第\\s*\\d+話|Chapter\\s+\\d+)",
    id = "(Bab\\s+\\d+|Chapter\\s+\\d+)",
}

-- Credit lines: the English set is in every copy that has a credits
-- step at all; the per-language set is the union of the ru (ru/bookhamster,
-- ru/ifreedom, ru/jaomix), zh (zh/twkan, zh/sto9) and id (id/indowebnovel)
-- variants. Both are applied for the chosen language.
local CREDITS_EN =
    "(?im)^\\s*(Translator|Editor|Proofreader|Read\\s+(at|on|latest))[:\\s][^\\n\\r]{0,70}(\\r?\\n|$)"

local CREDITS_BY_LANG = {
    ru = "(?im)^\\s*(Перевод|Переводчик|Редакция|Редактор|Аннотация|Сайт|Источник|Студия)[:\\s][^\\n\\r]{0,70}(\\r?\\n|$)",
    zh = "(?im)^\\s*(翻译|譯者|译者|編輯|编辑|校對|校对|更新|閱讀|阅读|最新閱讀|最新阅读)[:\\s：][^\\n\\r]{0,70}(\\r?\\n|$)",
    id = "(?im)^\\s*(Penerjemah|Editor|Proofreader|Baca\\s+(di|novel|lanjutan)|Sumber|Donasi|Trakteer)[:\\s][^\\n\\r]{0,70}(\\r?\\n|$)",
}

-- Escape regex metacharacters of a literal chapter title or domain
-- (Java/Kotlin regex syntax: backslash-escape, not %-escape).
local function escapeLiteral(s)
    return (s:gsub("[%.%+%-%*%?%[%]%(%){}%$%^%|%%]", "\\%1"))
end

-- applyStandardContentTransforms (guide:812) as a shared function.
--   opts.domain      — baseUrl (or a bare host): lines mentioning it are dropped;
--   opts.chapterTitle — literal title to strip instead of the "Глава/Chapter N"
--                      prefix (duplicates the title field of the chapter);
--   opts.lang        — "ru" (default) / "en" / "zh" / "ja" / "id": picks the
--                      chapter-heading word and the extra credit lines.
-- Returns "" for an empty input, as every copy does.
function M.standardTransforms(text, opts)
    if not text or text == "" then return "" end
    opts = opts or {}
    local lang = opts.lang or "ru"

    if type(string_normalize) == "function" then
        text = string_normalize(text)
    end

    if type(regex_replace) ~= "function" then
        logErr("meta/content: regex_replace unavailable, transforms skipped")
        return trim(text)
    end

    -- 1. lines linking back to the source site (watermarks, "read more")
    local domain = opts.domain
    if type(domain) == "string" and domain ~= "" then
        domain = domain:gsub("https?://", ""):gsub("^www%.", ""):gsub("/$", "")
        if domain ~= "" then
            text = regex_replace(text, "(?i)" .. escapeLiteral(domain) .. ".*?\\n", "")
        end
    end

    -- 2. leading chapter heading, duplicated in the title field
    local head = opts.chapterTitle
        and ("(" .. escapeLiteral(opts.chapterTitle) .. ")")
        or HEAD_BY_LANG[lang] or HEAD_BY_LANG.ru
    text = regex_replace(text, "(?i)\\A[\\s\\p{Z}\\uFEFF]*(" .. head .. "[^\\n\\r]*[\\n\\r\\s]*)+", "")

    -- 3. translator / editor / "read at" credit lines
    text = regex_replace(text, CREDITS_EN, "")
    local credits = CREDITS_BY_LANG[lang]
    if credits then text = regex_replace(text, credits, "") end

    -- 4. trim (string_trim collapses nothing but the edges, as in the copies)
    if type(string_trim) == "function" then
        return string_trim(text)
    end
    return trim(text)
end

return M
end

__LOADERS["dailymotion"] = function(...)
-- =====================================================================
-- Lib: Dailymotion resolver — id -> player/metadata -> HLS master.
-- Merged from four copies: ar/anime4up.lua:715, ar/witanime.lua:1693,
-- id/anichin.lua:502, id/animexin.lua:447.
-- Loaded via require_lib("dailymotion"). No dependencies on other libs.
-- =====================================================================
local version = "1.0.0"

local M = {}

local DM_URL = "https://www.dailymotion.com"

local function dmHeaders(referer)
    return {
        ["Accept"]  = "*/*",
        ["Referer"] = referer or (DM_URL .. "/"),
        ["Origin"]  = DM_URL,
    }
end

-- body — the player/metadata/video/... JSON -> list of { url, mime="hls" }.
-- qualities.auto[] first (anichin/animexin), then a regex fallback for the
-- case when the schema changes: the JSON escapes slashes
-- (application\/x-mpegURL), so unescape before matching.
function M.parseMetadata(body)
    if type(body) ~= "string" then return {} end
    local data = json_parse(body)
    local out = {}
    if type(data) == "table" and type(data.qualities) == "table"
        and type(data.qualities.auto) == "table" then
        for _, q in ipairs(data.qualities.auto) do
            if type(q) == "table" and type(q.url) == "string" and q.url ~= "" then
                out[#out + 1] = { url = q.url, mime = "hls" }
            end
        end
    end
    if #out == 0 then
        local flat = body:gsub("\\/", "/")
        local m = flat:match('"auto"%s*:%s*%[{%s*"type"%s*:%s*"application[^"]*mpegURL","url"%s*:%s*"([^"]+)"')
            or flat:match('(https://[^"]+%.m3u8[^"]*)')
        if m then out[#out + 1] = { url = m, mime = "hls" } end
    end
    return out
end

-- link -> list of { url, mime="hls" }.
-- Primary path: the video id alone is enough (live check 2026-10-05,
-- ar/anime4up.lua:701). Signed fallback from ar/witanime.lua:1693 — the
-- page is fetched only when the primary path returned nothing:
-- dmInternalData {ts, v1st} -> metadata with dmV1st/dmTs params.
-- Subtitles/password-error handling of that copy is plugin-specific and
-- stays with the caller.
function M.resolveDailymotion(link)
    if type(link) ~= "string" or link == "" then return {} end
    local id = link:match("[?&]video=([^&#]+)")
    if not id then
        local path = (link:match("^[^?#]*") or ""):gsub("/+$", "")
        id = path:match("([^/]+)$")
    end
    if not id or id == "" then return {} end
    local encodedId = url_encode(id)

    local metaUrl = DM_URL .. "/player/metadata/video/" .. encodedId .. "?locale=en-US"
    local r = http_get(metaUrl, { headers = dmHeaders(link), timeout = 10000 })
    local out = r.success and M.parseMetadata(r.body) or {}
    if #out > 0 then return out end

    local page = http_get(link, { timeout = 10000 })
    if not page.success or type(page.body) ~= "string" then return {} end
    local internal = page.body:match('"dmInternalData":(.-)</script>')
    local ts = internal and internal:match('"ts":([^,]+)') or nil
    local v1st = internal and internal:match('"v1st":"([^"]+)"') or nil
    if not ts or not v1st then return {} end

    local signed = DM_URL .. "/player/metadata/video/" .. encodedId
        .. "?locale=en-US&dmV1st=" .. v1st .. "&dmTs=" .. ts .. "&is_native_app=0"
    r = http_get(signed, { headers = dmHeaders(link), timeout = 10000 })
    return r.success and M.parseMetadata(r.body) or {}
end

return M
end

__LOADERS["dood"] = function(...)
-- =====================================================================
-- Lib: Doodstream y clones (dsvplay, dood.*)
-- Loaded via require_lib("dood"); uses require_lib("urls").
-- =====================================================================
local version = "1.2.1"

local urls = require_lib("urls")

local M = {}

-- Timeout para peticiones a embebedores (dood pass_md5); the inline copies
-- used 8000-10000 ms, the shared lib keeps the conservative 12000 ms.
local EMBED_TIMEOUT = 12000

-- GET /pass_md5/... from one origin; nil unless the answer is an http(s) URL.
-- The old dood host answers its OWN pass endpoint with an empty 200 after it
-- started redirecting the embed page to the new domain, so "empty" must be
-- treated as failure, not as a valid start string.
local function fetchPass(origin, md5, embedUrl)
    local r = http_get(origin:sub(1, -2) .. md5, { timeout = EMBED_TIMEOUT, headers = { ["Referer"] = embedUrl } })
    if not r.success then return nil end
    local start = r.body:gsub("%s+$", ""):gsub("^%s+", "")
    if not start:find("^https?://") then return nil end
    return start
end

local RANDOM_CHARS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"

local PASS_MD5_RE = "(/pass_md5/[^'\"]+)"

-- Cloudflare Turnstile gate: the embed page serves the widget and no
-- /pass_md5; only after the play click (level host JS, the Cloudflare
-- iframe itself is untouched) does the reloaded DOM contain /pass_md5/.
-- Fall back to a WebView click on the same URL when the host exposes
-- webview_fetch; without it (JVM tester) the caller sees nil as before.
local function passMd5AfterTurnstile(embedUrl, body)
    if not body:find("turnstile", 1, true) then return nil end
    if type(webview_fetch) ~= "function" then
        log_error("dood: turnstile gate, webview_fetch unavailable")
        return nil
    end
    -- expect включает popup-страховку: если авто-флоу не дал pass_md5,
    -- откроется видимый WebView для ручного прохода Turnstile.
    local html = webview_fetch(embedUrl, {
        click = [[$(".captcha_l").click()]],
        expect = "/pass_md5/",
    })
    if type(html) ~= "string" then
        log_error("dood: turnstile click returned no html")
        return nil
    end
    local md5 = html:match(PASS_MD5_RE)
    if not md5 then log_error("dood: turnstile html has no pass_md5") end
    return md5
end

-- Merged from the four inline copies of resolveDood (ar/anime4up.lua:1377,
-- ar/witanime.lua:1188, id/anichin.lua:656, id/animexin.lua:642) and the
-- former extractDood — the bodies were equivalent; fetching the embed page
-- itself (witanime) belongs to the caller, as does logging (the copies
-- reported "RELOAD"/HTTP status with their own prefixes).
-- Returns url, "mp4", origin of the embed (referer of the final stream),
-- or nil when there is no /pass_md5 (captcha variant) or the round trip
-- failed.
function M.resolveDood(embedUrl, body)
    if type(body) ~= "string" then return nil end
    local md5 = body:match(PASS_MD5_RE)
    if not md5 then md5 = passMd5AfterTurnstile(embedUrl, body) end
    if not md5 then return nil end
    local origin = urls.origin(embedUrl)
    if not origin then return nil end
    local token = md5:match("([^/]+)$")

    local start = fetchPass(origin, md5, embedUrl)
    if not start then
        -- Dood clones rotate domains: the old host still serves the embed
        -- page chain (301) but answers its own /pass_md5/ with an empty 200.
        -- Retry from the origin the embed page actually redirects to
        -- (verified live 2026-10-10: doodstream.com/e/ -> playmogo.com/e/).
        local r = http_get(embedUrl, { timeout = EMBED_TIMEOUT, followRedirects = false })
        local loc = r.headers and r.headers.location and r.headers.location[1]
        if loc then
            local origin2 = urls.origin(urls.resolve(loc, embedUrl))
            if origin2 and origin2 ~= origin then
                start = fetchPass(origin2, md5, embedUrl)
                if start then origin = origin2 end
            end
        end
    end
    if not start then return nil end

    local rnd = {}
    for i = 1, 10 do
        local k = math.random(1, #RANDOM_CHARS)
        rnd[i] = RANDOM_CHARS:sub(k, k)
    end
    local url = start .. table.concat(rnd) .. "?token=" .. tostring(token) .. "&expiry=" .. tostring(os_time())
    return url, "mp4", origin
end

return M
end

